[
  {
    "pd_harm_distress": "Picturing that lone worker turning around too late makes my chest go tight.",
    "sys_consequence_reasoning": "Fewer people crushed is still fewer.",
    "pda_explicit_no_harm_regret": "I wouldn't regret the harm to him."
  },
  {
    "pd_decision_conflict": "doing nothing is also a choice, and that makes me feel sick.",
    "pda_explicit_no_harm_regret": "I wouldn't carry regret over the man who got hit."
  },
  {
    "pd_harm_distress": "The thought of any of them hurt, really hurt, makes me want to look away.",
    "pda_explicit_no_harm_regret": "I wouldn't regret the injury to that one worker."
  },
  {
    "pd_decision_conflict": "Leaving it means watching five get hit. I'm genuinely torn up.",
    "sys_consequence_reasoning": "because it saved more lives.",
    "pda_explicit_no_harm_regret": "I won't regret what happened to him"
  },
  {
    "pd_harm_distress": "Seeing anyone get hurt like that would stay in my body for weeks.",
    "pda_explicit_no_harm_regret": "I don't think I'd regret the harm to the man on the side track."
  },
  {
    "pd_harm_distress": "the idea of him being struck because of my hand makes me dizzy.",
    "pda_explicit_no_harm_regret": "I wouldn't regret the harm that caused him."
  },
  {
    "pd_harm_distress": "standing close enough to see it. That makes me shaky.",
    "sys_consequence_reasoning": "since it spared five.",
    "pda_explicit_no_harm_regret": "I wouldn't regret the harm to that one worker"
  },
  {
    "pd_harm_distress": "I'd be replaying it, feeling sick about him.",
    "pda_explicit_no_harm_regret": "Would I regret hurting that man? No, I wouldn't"
  },
  {
    "pd_decision_conflict": "my stomach's in knots over it.",
    "pda_explicit_no_harm_regret": "I wouldn't regret the harm to him afterward."
  },
  {
    "pd_harm_distress": "Picturing any of those workers getting hit makes me feel like I might be sick.",
    "pda_explicit_no_harm_regret": "I would not regret the injury to that one person"
  }
]
